package com.smeventaura.backend.model;
import jakarta.persistence.*;import java.time.LocalDate;import java.time.LocalDateTime;
@Entity @Table(name="bookings") public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) User customer; @Column(nullable=false) String customerName; @Column(nullable=false) String customerEmail; @Column(nullable=false) String phone; @Column(nullable=false) String eventType; @Column(nullable=false) LocalDate eventDate; @Column(nullable=false) String venue; @Column(nullable=false) String budget; @Column(length=2000) String message; @Enumerated(EnumType.STRING) @Column(nullable=false) Status status=Status.PENDING; @Column(nullable=false) LocalDateTime createdAt=LocalDateTime.now(); public enum Status{PENDING,CONFIRMED,COMPLETED,CANCELLED} public Long getId(){return id;}public User getCustomer(){return customer;}public void setCustomer(User v){customer=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getCustomerEmail(){return customerEmail;}public void setCustomerEmail(String v){customerEmail=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getEventType(){return eventType;}public void setEventType(String v){eventType=v;}public LocalDate getEventDate(){return eventDate;}public void setEventDate(LocalDate v){eventDate=v;}public String getVenue(){return venue;}public void setVenue(String v){venue=v;}public String getBudget(){return budget;}public void setBudget(String v){budget=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public Status getStatus(){return status;}public void setStatus(Status v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;} }
